// Dump returns JSON-serializable diagnostics information about the connection pool.
// The returned map contains pool configuration and per-address connection status.
func (p *connPool) Dump() map[string]interface{} {
	result := make(map[string]interface{})
	result["pool_size"] = p.size
	result["remote_service"] = p.remoteService
	result["short_conn_mode"] = p.connOpts.ShortConn

	connections := make(map[string]interface{})
	p.conns.Range(func(key, value interface{}) bool {
		address := key.(string)
		trans := value.(*transports)

		connInfo := make(map[string]interface{})
		connInfo["capacity"] = trans.size
		connInfo["current_index"] = atomic.LoadUint32(&trans.index)

		activeCount := 0
		transports := make([]map[string]interface{}, 0, trans.size)
		for i := 0; i < int(trans.size); i++ {
			tr := trans.cliTransports[i]
			trInfo := make(map[string]interface{})
			if tr == nil {
				trInfo["status"] = "nil"
			} else if tr.(grpc.IsActive).IsActive() {
				trInfo["status"] = "active"
				activeCount++
			} else {
				trInfo["status"] = "inactive"
			}
			transports = append(transports, trInfo)
		}
		connInfo["active_count"] = activeCount
		connInfo["transports"] = transports

		connections[address] = connInfo
		return true
	})
	result["connections"] = connections
	result["total_addresses"] = len(connections)

	return result
}

// newTLSConn constructs a client-side TLS connection and performs handshake.
func newTLSConn(conn net.Conn, tlsCfg *tls.Config) (net.Conn, error) {
	tlsConn := tls.Client(conn, tlsCfg)
	if err := tlsConn.Handshake(); err != nil {
		return nil, err
	}
	return tlsConn, nil
}

