// readAndCheckFrameHeader reads and validates an HTTP/2 frame header.
// On validation failure, it logs a hex dump of the frame header for diagnostics.
func readAndCheckFrameHeader(r netpoll.Reader) (http2.FrameHeader, error) {
	fh, err := readFrameHeader(r)
	if err != nil {
		return fh, err
	}

	// Validate frame header fields
